#!/bin/bash
sed -i '/loadSocialData();/a \
      const unsubscribe = SocialService.subscribeToNotifications(user.authId || user.id, (notifs) => {\n        const mappedNotifs = notifs.map(n => ({\n          id: n.id,\n          authId: n.recipientId,\n          type: n.type as AppNotificationType,\n          title: n.title || (n.type === "friend_request" ? "Nova Solicitação" : n.type === "friend_accept" ? "Amizade Aceita" : n.type === "new_record" ? "Novo Recorde!" : n.type === "record_beaten" ? "Seu recorde foi superado!" : "Notificação"),\n          message: n.message || "",\n          timeAgo: "agora",\n          timestamp: n.createdAt ? new Date(n.createdAt?.toMillis ? n.createdAt.toMillis() : Date.now()).toISOString() : new Date().toISOString(),\n          isRead: !!n.read,\n          actionType: n.actionType || (n.type === "friend_request" ? "open_social_hub" : n.type === "friend_accept" ? "open_profile" : "open_zone"),\n          actionPayload: n.actionPayload || (n.type === "friend_request" ? { tab: "friends" } : n.type === "friend_accept" ? { playerId: n.senderId } : {})\n        }));\n        setNotifications((prev) => {\n          // Merge with INITIAL_NOTIFICATIONS or just overwrite?\n          // We will just use Firestore notifications\n          return mappedNotifs;\n        });\n      });\n      return () => unsubscribe();' src/App.tsx
